description:
Rewrite packages/solid-store/src/useSelector.ts. Target:

  import { createSignal, flush, getObserver, getOwner, onCleanup } from 'solid-js'
  import type { Accessor } from 'solid-js'

  export interface UseSelectorOptions<TSelected> {
    compare?: (a: TSelected, b: TSelected) => boolean
    /**
     * Settle the reactive graph when this accessor is read imperatively, so a
     * read immediately after a store write observes the new value. Off by
     * default: it costs a flush per untracked, unowned read.
     */
    settleOnRead?: boolean
  }

  export function useSelector<TSource, TSelected = NoInfer<TSource>>(
    source: SelectionSource<TSource>,
    selector: (snapshot: TSource) => TSelected = (s) => s as unknown as TSelected,
    options?: UseSelectorOptions<TSelected>,
  ): Accessor<TSelected> {
    const compare = options?.compare ?? defaultCompare
    const [signal, setSignal] = createSignal(
      selector(source.get()) as Exclude<TSelected, Function>,
      {
        equals: compare,
        // The producer is outside Solid's ownership: @tanstack/store calls this
        // callback synchronously from set(), which may be a component body or an
        // effect, and the write inherits that scope.
        ownedWrite: true,
        name: 'store/useSelector',
      },
    )

    const subscription = source.subscribe((snapshot) => {
      setSignal(() => selector(snapshot))
    })

    onCleanup(() => {
      subscription.unsubscribe()
    })

    if (!options?.settleOnRead) return signal

    return () => {
      // Both halves of this guard are load-bearing: flushing when merely
      // unobserved drains the queue into a mounting component's owned scope and
      // crashes with REACTIVE_WRITE_IN_OWNED_SCOPE.
      if (getObserver() === null && getOwner() === null) flush()
      return signal()
    }
  }

Unchanged from today: the SelectionSource<T> duck-type, defaultCompare, the
equals: compare semantics (returns true => equal => no update), and the
setSignal(() => value) functional-update escape for function-valued state.

Note getObserver() is NOT a tracking predicate - it returns non-null inside an
untracked component body. That is fine here, because in the settle guard an untracked
read is harmless either way; do not reuse it to answer "am I in a tracking scope".

Four files in packages/solid-store:
- tsconfig.json        (jsxImportSource: "solid-js" -> "@solidjs/web", add customConditions)
- tsconfig.build.json  (inherits from tsconfig.json; confirm it resolves correctly)
- tsconfig.source.json (sets jsxImportSource explicitly -> flip it)
- tsconfig.docs.json   (inherits; used by scripts/generate-docs.ts for TypeDoc)

Target for tsconfig.json:

  "compilerOptions": {
    "jsx": "preserve",
    "jsxImportSource": "@solidjs/web",
    // Match the runtime the tests execute under: vite-plugin-solid injects the
    // browser/development conditions in test mode, and solid-js maps the bare
    // node condition to the inert server build.
    "customConditions": ["browser", "development"],
    "paths": { "@tanstack/store": ["../store/src"] }
  }

Note tsconfig.build.json currently clears "paths" to {} - preserve that behaviour.

Add to packages/solid-store/eslint.config.js:

  {
    files: ['src/**'],
    rules: {
      'no-restricted-syntax': [
        'error',
        {
          selector:
            "CallExpression[callee.name=/^create(Render)?Effect$/][arguments.1.type='ArrowFunctionExpression'][arguments.1.body.type!='BlockStatement']",
          message:
            'Effect halves must be braced blocks returning undefined or a cleanup function: an expression-bodied arrow leaks its value into the cleanup slot and halts reactivity (REACTIVITY_HALTED).',
        },
      ],
    },
  }
